<?php $replies=all("SELECT r.*,c.first_name,c.last_name FROM ticket_replies r LEFT JOIN customers c ON c.id=r.customer_id WHERE r.ticket_id=? AND (?='admin' OR r.is_internal=0) ORDER BY r.id",[$ticket['id'],($isAdmin??false)&&admin()?'admin':'customer']); ?>
<div class="thread-grid"><section class="panel thread"><article class="thread-message"><div class="message-meta"><span class="avatar"><?= e(strtoupper(substr($ticket['customer_name']?:'K',0,1))) ?></span><div><strong><?= e($ticket['customer_name']?:'Kunde') ?></strong><small><?= date_de($ticket['created_at']) ?></small></div></div><div class="pre-wrap"><?= e($ticket['message']) ?></div></article><?php foreach($replies as $reply): ?><article class="thread-message <?= $reply['admin_id']?'staff-message':'' ?>"><div class="message-meta"><span class="avatar"><?= $reply['admin_id']?'OC':e(strtoupper(substr($reply['first_name']??'K',0,1))) ?></span><div><strong><?= $reply['admin_id']?'Server Management · Support':e(($reply['first_name']??'Kunde').' '.($reply['last_name']??'')) ?></strong><small><?= date_de($reply['created_at']) ?><?= $reply['is_internal']?' · Interne Notiz':'' ?></small></div></div><div class="pre-wrap"><?= e($reply['message']) ?></div></article><?php endforeach ?><form method="post" class="reply-form"><?= csrf() ?><input type="hidden" name="action" value="<?= $isAdmin?'admin_reply':'reply' ?>"><input type="hidden" name="id" value="<?= (int)$ticket['id'] ?>"><label class="field"><span><?= $isAdmin?'Antwort an den Kunden':'Deine Antwort' ?></span><textarea name="message" rows="5" maxlength="12000" required placeholder="Schreibe eine Nachricht …"><?= e($_POST['message']??'') ?></textarea></label><?php if($isAdmin):?><label><input type="checkbox" name="internal" value="1"> Interne Notiz (nur Verwaltung)</label><?php endif?><button class="button button-teal">Antwort senden <?= icon('arrow') ?></button><p class="form-footnote">Die Antwort wird im Ticketverlauf gespeichert.</p></form></section><aside class="panel aside-note"><h3>Ticketdetails</h3><dl class="detail-list"><div><dt>Ticketnummer</dt><dd><?= e($ticket['ticket_number']) ?></dd></div><div><dt>Status</dt><dd><?= badge($ticket['status']) ?></dd></div><div><dt>Kategorie</dt><dd><?= e(['technical'=>'Technik','billing'=>'Abrechnung','general'=>'Allgemein','account'=>'Konto'][$ticket['category']]??$ticket['category']) ?></dd></div><div><dt>Priorität</dt><dd><?= e(['low'=>'Niedrig','medium'=>'Normal','high'=>'Hoch','urgent'=>'Dringend'][$ticket['priority']]) ?></dd></div></dl><?php if($isAdmin): ?><form method="post"><?= csrf() ?><input type="hidden" name="action" value="admin_ticket_status"><input type="hidden" name="id" value="<?= (int)$ticket['id'] ?>"><label class="field"><span>Status ändern</span><select name="status"><?php foreach(['open','in_progress','waiting_customer','waiting_admin','resolved','closed'] as $status): ?><option <?= $ticket['status']===$status?'selected':'' ?> value="<?= $status ?>"><?= label($status) ?></option><?php endforeach ?></select></label><button class="button button-outline button-small">Speichern</button></form><?php endif ?></aside></div>
